from experiments.run_largecap_lowvol import summarize_basket
from experiments.run_market_gated_analyst import revision_breadth_states
def encode(value):return value.item() if hasattr(value,"item") else str(value)
FOLDS=(("discovery","2017-01-01","2022-12-31"),("validation","2023-01-01","2024-12-31"),("holdout","2025-01-01","2025-12-31"));BASELINE=.1432
def yearly_return(returns,year):
 x=returns[pd.to_datetime(returns.index).year==year];return float((1+x).prod()-1) if len(x) else 0.0
def run(raw_dir,start,end,benchmark_path,signals_path,nav_path,out_json,out_md,current_json,current_md):
 reports=load_reports(raw_dir);dates,lookup,targets30,signals,metadata=build_inputs(start,end,reports,"revision_to_price");signals.to_csv(signals_path,index=False,date_format="%Y-%m-%d");states,_=revision_breadth_states(signals,targets30,"signal_value");targets={date:(symbols[:10] if states[date] else []) for date,symbols in targets30.items()};config=BasketConfig(name="price_normalized_eps_top10",target_count=10,initial_nav=400000,buy_cost=.00155,sell_cost=.00155);gross_config=BasketConfig(name="price_normalized_eps_top10_gross",target_count=10,initial_nav=400000,buy_cost=0,sell_cost=0);result=simulate_basket(dates,lookup,targets,config);gross=simulate_basket(dates,lookup,targets,gross_config);benchmark=benchmark_returns(benchmark_path,dates);portfolio=summarize_basket(result,gross,benchmark,config,folds=FOLDS);pd.DataFrame({"date":result.dates,"nav":result.nav,"gross_nav":gross.nav,"benchmark_return":benchmark.to_numpy()}).to_csv(nav_path,index=False);validation=portfolio["folds"]["validation"];holdout=float(portfolio["yearly_returns"].get("2025",0));benchmark_2025=yearly_return(benchmark,2025);values=pd.to_numeric(signals.signal_value,errors="coerce");finite=bool(np.isfinite(values.dropna()).all());checks={"finite_signal":finite,"higher_cagr":portfolio["metrics"]["cagr"]>BASELINE,"validation":validation["cagr"]>0 and validation["excess_cagr"]>0,"holdout":holdout>0 and holdout>benchmark_2025,"sharpe":portfolio["metrics"]["sharpe"]>=.60,"drawdown":portfolio["metrics"]["max_drawdown"]>=-.50,"cost_retention":portfolio["gross_to_net_cagr_retention"]>=.80,"turnover":portfolio["annual_turnover"]<=12};payload={"study":"a-share-price-normalized-eps-revision-v14","authority":"exploratory_only_no_platform_prepare_operation","data":{**metadata,"enabled_months":sum(states.values()),"decision_months":len(states),"participation":sum(states.values())/len(states)},"signal_distribution":{"count":int(values.notna().sum()),"finite":finite,"min":float(values.min()),"p01":float(values.quantile(.01)),"median":float(values.median()),"p99":float(values.quantile(.99)),"max":float(values.max())},"portfolio":portfolio,"holdout_2025":{"strategy_return":holdout,"benchmark_return":benchmark_2025,"excess":holdout-benchmark_2025},"checks":checks,"verdict":"GO-HIGH-RETURN-CANDIDATE" if all(checks.values()) else "NO-GO","trade_authorized":False};Path(out_json).write_text(json.dumps(payload,ensure_ascii=False,indent=2,default=encode)+"\n");m=portfolio["metrics"];lines=["# A股价格归一化EPS修正V14结果","",f"- verdict: **{payload['verdict']}**",f"- CAGR/Sharpe/MDD: {m['cagr']:.2%} / {m['sharpe']:.3f} / {m['max_drawdown']:.2%}",f"- validation CAGR/excess: {validation['cagr']:.2%} / {validation['excess_cagr']:.2%}",f"- 2025 strategy/benchmark: {holdout:.2%} / {benchmark_2025:.2%}",f"- signal p01/median/p99: {payload['signal_distribution']['p01']:.3%} / {payload['signal_distribution']['median']:.3%} / {payload['signal_distribution']['p99']:.3%}"];Path(out_md).write_text("\n".join(lines)+"\n");last=max(targets);current={"as_of":end,"last_decision":last,"enabled":states[last],"targets":targets[last],"strategy_verdict":payload["verdict"],"trade_authorized":False};Path(current_json).write_text(json.dumps(current,ensure_ascii=False,indent=2)+"\n");Path(current_md).write_text("# A股价格归一化EPS修正当前状态\n\n"+f"- enabled: **{states[last]}**\n- targets: {len(targets[last])}\n- trade authorized: **NO**\n");print("\n".join(lines));return payload
def main(argv=None):
 p=argparse.ArgumentParser();p.add_argument("--raw-dir",default="overall/a-share-report-rc-raw");p.add_argument("--start",default="2017-01-03");p.add_argument("--end",default="2026-08-26");p.add_argument("--benchmark",default="overall/a-share-equity-etf-daily-current.csv");p.add_argument("--signals",default="overall/a-share-price-normalized-eps-signals.csv");p.add_argument("--nav",default="overall/a-share-price-normalized-eps-nav.csv");p.add_argument("--out-json",default="overall/a-share-price-normalized-eps-revision-v14-result.json");p.add_argument("--out-md",default="overall/a-share-price-normalized-eps-revision-v14-result.md");p.add_argument("--current-json",default="overall/a-share-price-normalized-eps-current.json");p.add_argument("--current-md",default="overall/a-share-price-normalized-eps-current.md");a=p.parse_args(argv);run(a.raw_dir,a.start,a.end,a.benchmark,a.signals,a.nav,a.out_json,a.out_md,a.current_json,a.current_md);return 0
